create trigger class_schema_immutable before update or delete on document.class_schema for each row execute function catalog.release_immutable();
alter table document.original add column class_id text not null default 'supplier-invoice',add column schema_version text not null default '1';
alter table document.original drop constraint original_mode_check;
alter table document.original add constraint original_mode_check check(mode in('FIXTURE','PROVIDER','TYPED_FIXTURE'));
alter table document.original add constraint original_class_fk foreign key(class_id,schema_version)references document.class_schema(class_id,schema_version);
create function document.guard_typed_original()returns trigger language plpgsql as $$begin
 if new.mode='TYPED_FIXTURE' then
  if not exists(select 1 from document.class_schema c where c.class_id=new.class_id and c.schema_version=new.schema_version and c.profile_sha256=new.profile_sha256 and c.fixture_sha256=new.original_sha256)then raise exception 'typed fixture bytes/profile/class not bound';end if;
 elsif new.class_id<>'supplier-invoice' or new.schema_version<>'1'then raise exception 'legacy class not supported';end if;
 return new;
end$$;
create trigger typed_original_guard before insert on document.original for each row execute function document.guard_typed_original();
create index document_inbox_scope on document.original(tenant_id,organization_id,received_at,document_id);
create index document_inbox_uploader on document.original(tenant_id,organization_id,uploader,received_at,document_id);
create function document.valid_typed_fields(cid text,ver text,f jsonb)returns boolean language plpgsql stable as $$
declare defs jsonb;d jsonb;v text;
begin
 select fields into defs from document.class_schema where class_id=cid and schema_version=ver;
 if defs is null or f is null or jsonb_typeof(f)<>'object' then return false;end if;
 if(select count(*)from jsonb_object_keys(f))<>jsonb_array_length(defs)then return false;end if;
 for d in select value from jsonb_array_elements(defs) loop
  if jsonb_typeof(f->(d->>'key')) is distinct from 'string' then return false;end if;
  v:=f->>(d->>'key');
  if v is null or octet_length(v)<1 or octet_length(v)>(d->>'max_length')::integer or v<>btrim(v) or v~'[[:cntrl:]]'then return false;end if;
  case d->>'type'
   when 'date' then if v!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'then return false;end if;begin if to_char(v::date,'YYYY-MM-DD')<>v then return false;end if;exception when others then return false;end;
   when 'decimal' then if v!~'^(0|[1-9][0-9]{0,17})([.][0-9]{1,8})?$'then return false;end if;
   when 'integer' then if v!~'^(0|[1-9][0-9]{0,8})$'then return false;end if;
   when 'currency' then if v!~'^[A-Z]{3}$'then return false;end if;
   when 'text' then null;
   else return false;
  end case;
 end loop;return true;
end$$;
create or replace function document.guard_review()returns trigger language plpgsql as $$
begin
 if new.kind='document_review' and not exists(
 select 1 from document.original o join document.extraction e using(tenant_id,document_id)
 where o.tenant_id=new.tenant_id and o.document_id::text=new.payload->>'document_id'
 and o.organization_id=new.organization_id and o.original_sha256=new.payload->>'original_sha256'
 and o.profile_sha256=new.payload->>'profile_sha256'and o.mode=new.payload->>'mode'
 and e.evidence_sha256=new.payload->>'evidence_sha256'
 and ((o.mode<>'TYPED_FIXTURE' and new.payload->>'schema'='document-review/v1'
 and jsonb_typeof(new.payload->'fields')='object'
 and(select count(*)from jsonb_object_keys(new.payload->'fields'))=4
 and jsonb_typeof(new.payload->'fields'->'invoice_number')='string'and octet_length(new.payload->'fields'->>'invoice_number')between 1 and 128
 and jsonb_typeof(new.payload->'fields'->'vendor')='string'and octet_length(new.payload->'fields'->>'vendor')between 1 and 512
 and jsonb_typeof(new.payload->'fields'->'total')='string'and octet_length(new.payload->'fields'->>'total')between 1 and 64
 and jsonb_typeof(new.payload->'fields'->'currency')='string'and(new.payload->'fields'->>'currency')~'^[A-Z]{3}$'
 and not exists(select 1 from jsonb_each_text(new.payload->'fields')f where f.value<>btrim(f.value)or f.value='')
 ) or (o.mode='TYPED_FIXTURE' and new.payload->>'schema'='document-review/v2' and new.payload->>'class_id'=o.class_id and new.payload->>'schema_version'=o.schema_version and document.valid_typed_fields(o.class_id,o.schema_version,new.payload->'fields')) )
 )then raise exception 'document review evidence not bound';end if;
 return new;
end$$;
commit;
